//! Rust source emission.

use std::collections::{BTreeMap, BTreeSet};
use std::fmt::Write as _;

use crate::Result;
use crate::config::{ENUM_VARIANT_NAMES, Module};
use crate::cpp_enums::EnumDef;
use crate::cpp_type::{CppType, has_default_by_default};
use crate::model::{Child, Class, Home, Member, Model, Shape};
use crate::names::{camel_case, rust_type_name};
use crate::spec::MemberStatus;

/// Variants whose payload is estimated to be larger than this are boxed, keeping the
/// kind enums (and so every tree node) small.
const BOX_THRESHOLD: usize = 64;

/// Builds one generated file, tracking the `use` items it needs.
pub struct Emitter<'m> {
    model: &'m Model,
    home: Home,
    derives: &'static [&'static str],
    imports: BTreeSet<String>,
    body: String,
}

/// How an explicit `default` from the spec is expressed.
enum DefaultExpr {
    /// `Value()`: a NULL value; compared with `is_null()`.
    NullValue,
    /// `optional_idx()`.
    InvalidIndex,
    Expr(String),
}

const SERDE: &str = "rustdb_serde";

impl<'m> Emitter<'m> {
    pub fn new(model: &'m Model, home: Home, derives: &'static [&'static str]) -> Self {
        Self {
            model,
            home,
            derives,
            imports: BTreeSet::new(),
            body: String::new(),
        }
    }

    /// The finished file.
    pub fn finish(self, source: &str) -> String {
        let mut out = format!("//! Generated by `tools/codegen` from DuckDB's {source}; do not edit.\n\n");
        let mut groups: BTreeMap<&str, Vec<&str>> = BTreeMap::new();
        for import in &self.imports {
            let (prefix, name) = import.rsplit_once("::").unwrap_or(("", import));
            groups.entry(prefix).or_default().push(name);
        }
        for (prefix, names) in &groups {
            if let [name] = names.as_slice() {
                let _ = writeln!(out, "use {prefix}::{name};");
            } else {
                let _ = writeln!(out, "use {prefix}::{{{}}};", names.join(", "));
            }
        }
        if !groups.is_empty() {
            out.push('\n');
        }
        out.push_str(&self.body);
        out
    }

    fn import(&mut self, path: &str) -> String {
        let name = path.rsplit("::").next().unwrap_or(path).to_owned();
        self.imports.insert(path.to_owned());
        name
    }

    fn serde(&mut self, item: &str) -> String {
        if self.home.crate_name == SERDE {
            format!("crate::{item}")
        } else {
            self.import(&format!("{SERDE}::{item}"))
        }
    }

    /// A named type, imported unless it is defined in this module.
    fn named(&mut self, name: &str) -> Result<String> {
        let defined_here = self
            .model
            .classes
            .get(name)
            .is_some_and(|c| c.home == self.home && !c.config.custom)
            || self.model.enum_homes.get(name).is_some_and(|h| *h == self.home);
        if defined_here {
            return Ok(self
                .model
                .classes
                .get(name)
                .map_or_else(|| rust_type_name(name), |c| c.rust_name.clone()));
        }
        let path = self.model.named_path(name, &self.home)?;
        Ok(self.import(&path))
    }

    /// The Rust type of a member type. Pointers become `Option<Box<T>>` (or `Box<T>` when
    /// `required`) at the top level and disappear inside containers, where every element
    /// is a present value.
    fn rust_type(&mut self, ty: &CppType, top: bool, required: bool) -> Result<String> {
        Ok(match ty {
            CppType::Bool => "bool".into(),
            CppType::U8 => "u8".into(),
            CppType::I8 => "i8".into(),
            CppType::U16 => "u16".into(),
            CppType::I16 => "i16".into(),
            CppType::U32 => "u32".into(),
            CppType::I32 => "i32".into(),
            CppType::U64 => "u64".into(),
            CppType::I64 => "i64".into(),
            CppType::F32 => "f32".into(),
            CppType::F64 => "f64".into(),
            CppType::I128 => "i128".into(),
            CppType::U128 => "u128".into(),
            CppType::String => "String".into(),
            CppType::OptionalIdx => "Option<u64>".into(),
            CppType::Named(name) => self.named(name)?,
            CppType::Pointer(inner) => {
                let inner = self.rust_type(inner, false, false)?;
                match (top, required) {
                    (false, _) => inner,
                    (true, true) => format!("Box<{inner}>"),
                    (true, false) => format!("Option<Box<{inner}>>"),
                }
            }
            CppType::Vector(inner) => format!("Vec<{}>", self.rust_type(inner, false, false)?),
            CppType::Set(inner) => {
                let set = self.import("std::collections::BTreeSet");
                format!("{set}<{}>", self.rust_type(inner, false, false)?)
            }
            CppType::CaseInsensitiveMap(inner) => {
                let map = self.import("rustdb_common::CaseInsensitiveMap");
                format!("{map}<{}>", self.rust_type(inner, false, false)?)
            }
            CppType::CaseInsensitiveSet => self.import("rustdb_common::CaseInsensitiveSet"),
            CppType::Map(key, value) => {
                let map = self.import("rustdb_common::OrderedMap");
                let key = self.rust_type(key, false, false)?;
                format!("{map}<{key}, {}>", self.rust_type(value, false, false)?)
            }
            CppType::Pair(a, b) => {
                let a = self.rust_type(a, false, false)?;
                format!("({a}, {})", self.rust_type(b, false, false)?)
            }
        })
    }

    fn member_type(&mut self, member: &Member) -> Result<String> {
        if member.spec.base.is_some() {
            let CppType::Pointer(inner) = &member.ty else {
                return Err(format!("member {} with a base must be a pointer", member.spec.name).into());
            };
            let inner = self.rust_type(inner, false, false)?;
            return Ok(if member.required() {
                inner
            } else {
                format!("Option<Box<{inner}>>")
            });
        }
        self.rust_type(&member.ty, true, member.required())
    }

    /// Rough in-memory size of a type, used to decide which variants to box.
    fn estimate_size(&self, ty: &CppType, depth: usize) -> usize {
        match ty {
            CppType::Bool | CppType::U8 | CppType::I8 => 1,
            CppType::U16 | CppType::I16 => 2,
            CppType::U32 | CppType::I32 | CppType::F32 => 4,
            CppType::U64 | CppType::I64 | CppType::F64 | CppType::Pointer(_) => 8,
            CppType::I128 | CppType::U128 | CppType::OptionalIdx => 16,
            CppType::String
            | CppType::Vector(_)
            | CppType::Set(_)
            | CppType::CaseInsensitiveMap(_)
            | CppType::CaseInsensitiveSet
            | CppType::Map(..) => 24,
            CppType::Pair(a, b) => self.estimate_size(a, depth) + self.estimate_size(b, depth),
            CppType::Named(name) => match name.as_str() {
                "LogicalType" => 16,
                "Value" => 48,
                _ if self.model.is_enum(name) => 1,
                _ => self
                    .model
                    .classes
                    .get(name)
                    .filter(|_| depth < 8)
                    .map_or(24, |class| self.class_size(class, depth + 1)),
            },
        }
    }

    fn class_size(&self, class: &Class, depth: usize) -> usize {
        class
            .data_members()
            .filter(|m| m.status == MemberStatus::Existing)
            .map(|m| self.estimate_size(&m.ty, depth))
            .sum()
    }

    fn is_boxed(&self, child: &Class) -> bool {
        self.class_size(child, 0) > BOX_THRESHOLD
    }

    // ------------------------------------------------------------------ enums

    pub fn emit_enum(&mut self, name: &str, def: &EnumDef) -> Result<()> {
        let rust = rust_type_name(name);
        let renames = ENUM_VARIANT_NAMES
            .iter()
            .find(|(e, _)| *e == name)
            .map_or(&[][..], |(_, r)| *r);
        let variant = |member: &str| {
            renames
                .iter()
                .find(|(m, _)| *m == member)
                .map_or_else(|| camel_case(member), |(_, v)| (*v).to_owned())
        };
        let (repr, write, read) = match def.underlying.as_str() {
            "uint8_t" => ("u8", "write_u8", "read_u8"),
            "int8_t" => ("i8", "write_i8", "read_i8"),
            "uint16_t" => ("u16", "write_u16", "read_u16"),
            "int16_t" => ("i16", "write_i16", "read_i16"),
            "uint32_t" => ("u32", "write_u32", "read_u32"),
            "int32_t" | "int" => ("i32", "write_i32", "read_i32"),
            "uint64_t" | "idx_t" => ("u64", "write_u64", "read_u64"),
            "int64_t" => ("i64", "write_i64", "read_i64"),
            other => return Err(format!("{name}: unsupported underlying type {other}").into()),
        };
        let serialize = self.serde("Serialize");
        let deserialize = self.serde("Deserialize");
        let serializer = self.serde("Serializer");
        let deserializer = self.serde("Deserializer");
        let result = self.serde("Result");
        let write_enum = self.serde("write_enum");
        let read_enum = self.serde("read_enum");

        let b = &mut self.body;
        let _ = writeln!(b, "/// DuckDB's `{name}` (`{}`).", def.header);
        let _ = writeln!(
            b,
            "#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]"
        );
        let _ = writeln!(b, "#[repr({repr})]");
        let _ = writeln!(b, "pub enum {rust} {{");
        for member in &def.members {
            let _ = writeln!(b, "    {} = {},", variant(&member.name), member.value);
        }
        let _ = writeln!(b, "}}\n");

        let _ = writeln!(b, "impl {rust} {{");
        let _ = writeln!(b, "    /// Every member, in declaration order.");
        let _ = writeln!(b, "    pub const ALL: [Self; {}] = [", def.members.len());
        for member in &def.members {
            let _ = writeln!(b, "        Self::{},", variant(&member.name));
        }
        let _ = writeln!(b, "    ];\n");
        let _ = writeln!(b, "    /// The name `EnumUtil::ToChars` prints.");
        let _ = writeln!(b, "    pub const fn name(self) -> &'static str {{");
        let _ = writeln!(b, "        match self {{");
        for member in &def.members {
            let _ = writeln!(
                b,
                "            Self::{} => {:?},",
                variant(&member.name),
                member.strings[0]
            );
        }
        let _ = writeln!(b, "        }}\n    }}\n");
        let _ = writeln!(
            b,
            "    /// Parses any name `EnumUtil::FromString` accepts (ASCII case-insensitive)."
        );
        let _ = writeln!(b, "    pub fn from_name(name: &str) -> Option<Self> {{");
        let _ = writeln!(b, "        const NAMES: &[(&str, {rust})] = &[");
        for member in &def.members {
            for string in &member.strings {
                let _ = writeln!(b, "            ({string:?}, {rust}::{}),", variant(&member.name));
            }
        }
        let _ = writeln!(b, "        ];");
        let _ = writeln!(
            b,
            "        NAMES.iter().find(|(n, _)| n.eq_ignore_ascii_case(name)).map(|(_, v)| *v)"
        );
        let _ = writeln!(b, "    }}\n");
        let _ = writeln!(b, "    /// The member with this numeric value.");
        let _ = writeln!(b, "    pub const fn from_repr(value: {repr}) -> Option<Self> {{");
        let _ = writeln!(b, "        match value {{");
        for member in &def.members {
            let _ = writeln!(
                b,
                "            {} => Some(Self::{}),",
                member.value,
                variant(&member.name)
            );
        }
        let _ = writeln!(b, "            _ => None,\n        }}\n    }}\n}}\n");

        let _ = writeln!(b, "impl {serialize} for {rust} {{");
        let _ = writeln!(
            b,
            "    fn serialize(&self, serializer: &mut dyn {serializer}) -> {result}<()> {{"
        );
        let _ = writeln!(
            b,
            "        {write_enum}(serializer, self.name(), |serializer| {{ serializer.{write}(*self as {repr}); }});"
        );
        let _ = writeln!(b, "        Ok(())\n    }}\n}}\n");
        let _ = writeln!(b, "impl {deserialize} for {rust} {{");
        let _ = writeln!(
            b,
            "    fn deserialize(deserializer: &mut dyn {deserializer}) -> {result}<Self> {{"
        );
        let _ = writeln!(
            b,
            "        {read_enum}(deserializer, {name:?}, Self::from_name, |deserializer| Ok(Self::from_repr(deserializer.{read}()?)))"
        );
        let _ = writeln!(b, "    }}\n}}\n");
        Ok(())
    }

    // ---------------------------------------------------------------- classes

    pub fn emit_class(&mut self, class: &Class) -> Result<()> {
        if class.config.custom {
            // Hand-written; subclasses of a custom root are still generated as plain structs.
            return Ok(());
        }
        let is_child_unit = class.spec.base.is_some() && class.members.is_empty();
        if is_child_unit {
            return Ok(());
        }
        match class.shape {
            Shape::Plain => self.emit_struct(class)?,
            Shape::Enum => self.emit_enum_root(class)?,
            Shape::StructWithKind => self.emit_struct_with_kind(class)?,
        }
        self.emit_serde_macro(class);
        Ok(())
    }

    fn emit_serde_macro(&mut self, class: &Class) {
        if !class.config.null_variants.is_empty() {
            return;
        }
        // Subclasses are only ever written through their hierarchy root.
        let macro_name = if class.pointer_held {
            "impl_pointee_serde"
        } else if class.spec.base.is_none() {
            "impl_object_serde"
        } else {
            return;
        };
        let _ = writeln!(self.body, "{SERDE}::{macro_name}!({});\n", class.rust_name);
    }

    fn derives(&self, class: &Class) -> String {
        let mut derives = vec!["Clone", "Debug"];
        for derive in self.derives.iter().chain(class.config.derives) {
            if !derives.contains(derive) {
                derives.push(derive);
            }
        }
        format!("#[derive({})]", derives.join(", "))
    }

    fn field_doc(member: &Member) -> String {
        format!("    /// `{}` (property {}).\n", member.spec.name, member.spec.id)
    }

    /// Fields of a struct: data members that are still part of the format, plus extra
    /// in-memory fields.
    fn emit_fields(&mut self, class: &Class) -> Result<()> {
        let members: Vec<&Member> = class
            .data_members()
            .filter(|m| m.status == MemberStatus::Existing)
            .collect();
        for member in members {
            let ty = self.member_type(member)?;
            let doc = Self::field_doc(member);
            let _ = writeln!(self.body, "{doc}    pub {}: {ty},", member.rust_name);
        }
        Ok(())
    }

    fn emit_struct(&mut self, class: &Class) -> Result<()> {
        let _ = writeln!(self.body, "/// DuckDB's `{}`.", class.spec.class);
        let _ = writeln!(self.body, "{}", self.derives(class));
        let _ = writeln!(self.body, "pub struct {} {{", class.rust_name);
        self.emit_fields(class)?;
        let _ = writeln!(self.body, "}}\n");
        self.emit_plain_serialize(class)?;
        self.emit_plain_deserialize(class)
    }

    fn emit_plain_serialize(&mut self, class: &Class) -> Result<()> {
        let trait_name = self.serde("SerializeObject");
        let serializer = self.serde("Serializer");
        let result = self.serde("Result");
        let mut body = String::new();
        for member in &class.members {
            body.push_str(&self.write_member(class, member)?);
        }
        let _ = writeln!(self.body, "impl {trait_name} for {} {{", class.rust_name);
        let _ = writeln!(
            self.body,
            "    fn serialize_fields(&self, serializer: &mut dyn {serializer}) -> {result}<()> {{"
        );
        self.body.push_str(&body);
        let _ = writeln!(self.body, "        Ok(())\n    }}\n}}\n");
        Ok(())
    }

    fn emit_plain_deserialize(&mut self, class: &Class) -> Result<()> {
        let trait_name = self.serde("DeserializeObject");
        let deserializer = self.serde("Deserializer");
        let result = self.serde("Result");
        let mut body = String::new();
        for member in &class.members {
            body.push_str(&self.read_member(class, member, false)?);
        }
        let fields = Self::field_list(class);
        let _ = writeln!(self.body, "impl {trait_name} for {} {{", class.rust_name);
        let _ = writeln!(
            self.body,
            "    fn deserialize_fields(deserializer: &mut dyn {deserializer}) -> {result}<Self> {{"
        );
        self.body.push_str(&body);
        let _ = writeln!(self.body, "        Ok(Self {{ {fields} }})\n    }}\n}}\n");
        Ok(())
    }

    fn field_list(class: &Class) -> String {
        class
            .data_members()
            .filter(|m| m.status == MemberStatus::Existing)
            .map(|m| m.rust_name.clone())
            .collect::<Vec<_>>()
            .join(", ")
    }

    fn child_class(&self, child: &Child) -> Result<&'m Class> {
        self.model
            .classes
            .get(&child.class)
            .ok_or_else(|| format!("unknown subclass {}", child.class).into())
    }

    /// The `class_type` enum and its variant path for `value`.
    fn discriminant_value(&mut self, class: &Class, value: &str) -> Result<String> {
        let (enum_name, _) = class.discriminant.as_ref().ok_or("not a hierarchy root")?;
        let def = self
            .model
            .enums
            .get(enum_name)
            .ok_or_else(|| format!("unknown enum {enum_name}"))?;
        if !def.members.iter().any(|m| m.name == value) {
            return Err(format!("{enum_name} has no member {value}").into());
        }
        let ty = self.named(enum_name)?;
        let variant = ENUM_VARIANT_NAMES
            .iter()
            .find(|(e, _)| e == enum_name)
            .and_then(|(_, r)| r.iter().find(|(m, _)| *m == value))
            .map_or_else(|| camel_case(value), |(_, v)| (*v).to_owned());
        Ok(format!("{ty}::{variant}"))
    }

    /// Variant declarations and the discriminant method for a hierarchy root.
    fn emit_kind_enum(&mut self, class: &Class, enum_name: &str, doc: &str) -> Result<()> {
        let (disc_enum, _) = class.discriminant.clone().ok_or("not a hierarchy root")?;
        let disc_ty = self.named(&disc_enum)?;
        let method = class.discriminant_method().ok_or("not a hierarchy root")?;
        let _ = writeln!(self.body, "{doc}");
        let derives = self.derives(class);
        let _ = writeln!(self.body, "{derives}");
        let _ = writeln!(self.body, "pub enum {enum_name} {{");
        let mut arms = Vec::new();
        for child in class.children.iter().filter(|c| !c.variant.is_empty()) {
            let child_class = self.child_class(child)?;
            let value = self.discriminant_value(class, &child.enum_value)?;
            let _ = writeln!(
                self.body,
                "    /// `{}` (`{}::{}`).",
                child_class.spec.class, disc_enum, child.enum_value
            );
            if child_class.members.is_empty() && !child_class.config.custom {
                let _ = writeln!(self.body, "    {},", child.variant);
                arms.push(format!("Self::{} => {value},", child.variant));
            } else {
                let ty = self.named(&child.class)?;
                let ty = if self.is_boxed(child_class) {
                    format!("Box<{ty}>")
                } else {
                    ty
                };
                let _ = writeln!(self.body, "    {}({ty}),", child.variant);
                arms.push(format!("Self::{}(_) => {value},", child.variant));
            }
        }
        let _ = writeln!(self.body, "}}\n");
        let _ = writeln!(self.body, "impl {enum_name} {{");
        let _ = writeln!(
            self.body,
            "    /// The `{disc_enum}` this subclass is serialized with."
        );
        let _ = writeln!(self.body, "    pub const fn {method}(&self) -> {disc_ty} {{");
        let _ = writeln!(self.body, "        match self {{");
        for arm in arms {
            let _ = writeln!(self.body, "            {arm}");
        }
        let _ = writeln!(self.body, "        }}\n    }}\n");
        Ok(())
    }

    /// `match self { ... }` writing the subclass members.
    fn serialize_kind_match(&self, class: &Class) -> Result<String> {
        // Variants of the same subclass (several `class_type` values) share one arm.
        let mut patterns: Vec<(&str, Vec<String>)> = Vec::new();
        let mut units = Vec::new();
        for child in class.children.iter().filter(|c| !c.variant.is_empty()) {
            let child_class = self.child_class(child)?;
            if child_class.members.is_empty() && !child_class.config.custom {
                units.push(format!("Self::{}", child.variant));
            } else if let Some((_, group)) = patterns.iter_mut().find(|(class, _)| *class == child.class) {
                group.push(format!("Self::{}(value)", child.variant));
            } else {
                patterns.push((&child.class, vec![format!("Self::{}(value)", child.variant)]));
            }
        }
        let mut arms: Vec<String> = patterns
            .iter()
            .map(|(_, group)| format!("{} => value.serialize_fields(serializer),", group.join(" | ")))
            .collect();
        if !units.is_empty() {
            arms.push(format!("{} => Ok(()),", units.join(" | ")));
        }
        Ok(format!("match self {{\n{}\n}}", arms.join("\n")))
    }

    /// `match <discriminant> { ... }` reading the subclass, as an expression of `kind_path`.
    /// Values without a subclass are listed explicitly, so that new enum members fail to
    /// compile until handled.
    fn deserialize_kind_match(&mut self, class: &Class, kind_path: &str) -> Result<String> {
        let (enum_name, _) = class.discriminant.clone().ok_or("not a hierarchy root")?;
        let local = class.discriminant_method().ok_or("not a hierarchy root")?;
        let mut arms = Vec::new();
        let mut covered = BTreeSet::new();
        for child in &class.children {
            let child_class = self.child_class(child)?;
            covered.insert(child.enum_value.clone());
            let value = self.discriminant_value(class, &child.enum_value)?;
            let expr = if let Some(arm) = child_class.config.deserialize_arm {
                arm.to_owned()
            } else if child_class.members.is_empty() && !child_class.config.custom {
                format!("{kind_path}::{}", child.variant)
            } else {
                let ty = self.named(&child.class)?;
                let read = format!("{ty}::deserialize_fields(deserializer)?");
                let read = if self.is_boxed(child_class) {
                    format!("Box::new({read})")
                } else {
                    read
                };
                format!("{kind_path}::{}({read})", child.variant)
            };
            arms.push(format!("{value} => {expr},"));
        }
        let uncovered: Vec<String> = self
            .model
            .enums
            .get(&enum_name)
            .map(|def| {
                def.members
                    .iter()
                    .filter(|m| !covered.contains(&m.name))
                    .map(|m| m.name.clone())
                    .collect()
            })
            .unwrap_or_default();
        if !uncovered.is_empty() {
            let values = uncovered
                .iter()
                .map(|value| self.discriminant_value(class, value))
                .collect::<Result<Vec<_>>>()?;
            let error = self.serde("Error");
            arms.push(format!(
                "{} => return Err({error}::serialization(\"Unsupported type for deserialization of {}!\")),",
                values.join(" | "),
                class.spec.class
            ));
        }
        Ok(format!("match {local} {{\n{}\n}}", arms.join("\n")))
    }

    fn emit_enum_root(&mut self, class: &Class) -> Result<()> {
        let doc = format!(
            "/// DuckDB's `{}` hierarchy: one variant per subclass.",
            class.spec.class
        );
        self.emit_kind_enum(class, &class.rust_name.clone(), &doc)?;
        let _ = writeln!(self.body, "}}\n");
        // Serialization: the discriminant, then the subclass members.
        let trait_name = self.serde("SerializeObject");
        let serializer = self.serde("Serializer");
        let result = self.serde("Result");
        let method = class.discriminant_method().ok_or("not a hierarchy root")?;
        let (_, index) = class.discriminant.clone().ok_or("not a hierarchy root")?;
        let disc = &class.members[index];
        let kind_match = self.serialize_kind_match(class)?;
        let _ = writeln!(self.body, "impl {trait_name} for {} {{", class.rust_name);
        let _ = writeln!(
            self.body,
            "    fn serialize_fields(&self, serializer: &mut dyn {serializer}) -> {result}<()> {{"
        );
        let _ = writeln!(
            self.body,
            "        serializer.write_property({}, {:?}, &self.{method}())?;",
            disc.spec.id, disc.spec.name
        );
        let _ = writeln!(self.body, "        {kind_match}\n    }}\n}}\n");

        let trait_name = self.serde("DeserializeObject");
        let deserializer = self.serde("Deserializer");
        let disc_ty = self.rust_type(&disc.ty, true, false)?;
        let kind_match = self.deserialize_kind_match(class, "Self")?;
        let _ = writeln!(self.body, "impl {trait_name} for {} {{", class.rust_name);
        let _ = writeln!(
            self.body,
            "    fn deserialize_fields(deserializer: &mut dyn {deserializer}) -> {result}<Self> {{"
        );
        let _ = writeln!(
            self.body,
            "        let {method}: {disc_ty} = deserializer.read_property({}, {:?})?;",
            disc.spec.id, disc.spec.name
        );
        let _ = writeln!(self.body, "        Ok({kind_match})\n    }}\n}}\n");
        Ok(())
    }

    fn emit_struct_with_kind(&mut self, class: &Class) -> Result<()> {
        let kind_name = class.kind_name();
        let method = class.discriminant_method().ok_or("not a hierarchy root")?;
        let (disc_enum, index) = class.discriminant.clone().ok_or("not a hierarchy root")?;
        let disc = &class.members[index];
        let disc_ty = self.named(&disc_enum)?;

        let _ = writeln!(
            self.body,
            "/// DuckDB's `{}`: the members shared by all subclasses, with the subclass in `kind`.",
            class.spec.class
        );
        let _ = writeln!(self.body, "{}", self.derives(class));
        let _ = writeln!(self.body, "pub struct {} {{", class.rust_name);
        self.emit_fields(class)?;
        let _ = writeln!(
            self.body,
            "    /// The subclass, serialized as `{}` (property {}).\n    pub kind: {kind_name},",
            disc.spec.name, disc.spec.id
        );
        let _ = writeln!(self.body, "}}\n");

        let _ = writeln!(self.body, "impl {} {{", class.rust_name);
        let _ = writeln!(self.body, "    /// The `{disc_enum}` of this object's subclass.");
        let _ = writeln!(
            self.body,
            "    pub const fn {method}(&self) -> {disc_ty} {{\n        self.kind.{method}()\n    }}\n}}\n"
        );

        let doc = format!(
            "/// The subclasses of [`{}`], selected by its `{disc_enum}`.",
            class.rust_name
        );
        self.emit_kind_enum(class, &kind_name, &doc)?;
        let kind_match = self.serialize_kind_match(class)?;
        let serializer = self.serde("Serializer");
        let result = self.serde("Result");
        let _ = writeln!(
            self.body,
            "    fn serialize_fields(&self, serializer: &mut dyn {serializer}) -> {result}<()> {{\n        {kind_match}\n    }}\n}}\n"
        );

        // Serialization of the root: members in order, the discriminant taken from `kind`.
        let trait_name = self.serde("SerializeObject");
        let mut body = String::new();
        for (i, member) in class.members.iter().enumerate() {
            if i == index {
                let _ = writeln!(
                    body,
                    "        serializer.write_property({}, {:?}, &self.kind.{method}())?;",
                    member.spec.id, member.spec.name
                );
            } else {
                body.push_str(&self.write_member(class, member)?);
            }
        }
        let _ = writeln!(self.body, "impl {trait_name} for {} {{", class.rust_name);
        let _ = writeln!(
            self.body,
            "    fn serialize_fields(&self, serializer: &mut dyn {serializer}) -> {result}<()> {{"
        );
        self.body.push_str(&body);
        let _ = writeln!(
            self.body,
            "        self.kind.serialize_fields(serializer)\n    }}\n}}\n"
        );

        // Deserialization: members, then the subclass selected by the discriminant.
        let deserializer = self.serde("Deserializer");
        let nullable = !class.config.null_variants.is_empty();
        let mutable_locals: BTreeSet<String> = class
            .children
            .iter()
            .filter_map(|c| self.model.classes.get(&c.class))
            .filter_map(|c| c.config.deserialize_arm)
            .flat_map(|arm| {
                class
                    .members
                    .iter()
                    .filter(move |m| arm.contains(&format!("&mut {}", m.rust_name)))
                    .map(|m| m.rust_name.clone())
            })
            .collect();
        let mut body = String::new();
        for (i, member) in class.members.iter().enumerate() {
            if i == index {
                let _ = writeln!(
                    body,
                    "        let {method}: {disc_ty} = deserializer.read_property({}, {:?})?;",
                    member.spec.id, member.spec.name
                );
            } else {
                let read = self.read_member(class, member, mutable_locals.contains(&member.rust_name))?;
                body.push_str(&read);
            }
        }
        let kind_match = self.deserialize_kind_match(class, &kind_name)?;
        let fields = Self::field_list(class);
        let fields = if fields.is_empty() {
            "kind".to_owned()
        } else {
            format!("{fields}, kind")
        };
        if nullable {
            let _ = writeln!(self.body, "impl {} {{", class.rust_name);
            let _ = writeln!(
                self.body,
                "    /// Reads the properties written by `serialize_fields`; some subclasses read as no object."
            );
            let _ = writeln!(
                self.body,
                "    pub fn deserialize_fields(deserializer: &mut dyn {deserializer}) -> {result}<Option<Self>> {{"
            );
            self.body.push_str(&body);
            let _ = writeln!(self.body, "        let kind = {kind_match};");
            let _ = writeln!(self.body, "        Ok(Some(Self {{ {fields} }}))\n    }}\n}}\n");
        } else {
            let trait_name = self.serde("DeserializeObject");
            let _ = writeln!(self.body, "impl {trait_name} for {} {{", class.rust_name);
            let _ = writeln!(
                self.body,
                "    fn deserialize_fields(deserializer: &mut dyn {deserializer}) -> {result}<Self> {{"
            );
            self.body.push_str(&body);
            let _ = writeln!(self.body, "        let kind = {kind_match};");
            let _ = writeln!(self.body, "        Ok(Self {{ {fields} }})\n    }}\n}}\n");
        }
        Ok(())
    }

    // ---------------------------------------------------------------- members

    fn default_expr(&mut self, member: &Member) -> Result<Option<DefaultExpr>> {
        let Some(default) = &member.spec.default else {
            return Ok(None);
        };
        let text = match default {
            serde_json::Value::Bool(b) => return Ok(Some(DefaultExpr::Expr(b.to_string()))),
            serde_json::Value::Number(n) => return Ok(Some(DefaultExpr::Expr(n.to_string()))),
            serde_json::Value::String(s) => s.clone(),
            other => return Err(format!("unsupported default {other}").into()),
        };
        if text == "true" || text == "false" {
            return Ok(Some(DefaultExpr::Expr(text)));
        }
        if text == "optional_idx()" {
            return Ok(Some(DefaultExpr::InvalidIndex));
        }
        if text == "Value()" {
            return Ok(Some(DefaultExpr::NullValue));
        }
        if let Some((enum_name, value)) = text.split_once("::")
            && self.model.is_enum(enum_name)
        {
            let ty = self.named(enum_name)?;
            let def = &self.model.enums[enum_name];
            if !def.members.iter().any(|m| m.name == value) {
                return Err(format!("default {text}: no such member").into());
            }
            return Ok(Some(DefaultExpr::Expr(format!("{ty}::{}", camel_case(value)))));
        }
        if text.ends_with("()") {
            // `unordered_map<string, Value>()` etc.: the Rust type's default.
            let ty = self.member_type(member)?;
            let path = ty.split('<').next().unwrap_or(&ty);
            return Ok(Some(DefaultExpr::Expr(format!("{path}::default()"))));
        }
        if text.starts_with('"') {
            return Ok(Some(DefaultExpr::Expr(format!("String::from({text})"))));
        }
        Err(format!("{}: unsupported default '{text}'", member.spec.name).into())
    }

    /// Statement(s) writing one member.
    fn write_member(&mut self, class: &Class, member: &Member) -> Result<String> {
        let serialize_with = member.config.and_then(|c| c.serialize_with);
        let conditional = member.version != 1;
        let write = match (member.status, conditional) {
            (MemberStatus::Existing, _) => true,
            (_, true) => {
                if serialize_with.is_none() {
                    return Err(format!(
                        "{}.{}: written for old versions only; needs serialize_with",
                        class.spec.class, member.spec.name
                    )
                    .into());
                }
                true
            }
            (_, false) => false,
        };
        if !write {
            return Ok(format!(
                "        // `{}` ({}) is no longer written.\n",
                member.spec.name, member.spec.id
            ));
        }
        let (id, tag) = (member.spec.id, &member.spec.name);
        let value = match serialize_with {
            Some(expr) => format!("({expr})"),
            None => format!("self.{}", member.rust_name),
        };
        let stmt = if member.spec.base.is_some() {
            self.write_base_member(class, member)?
        } else {
            match self.default_expr(member)? {
                Some(DefaultExpr::NullValue) => {
                    format!("serializer.write_optional({id}, {tag:?}, {value}.is_null(), &{value})?;")
                }
                Some(DefaultExpr::InvalidIndex) => {
                    let idx = self.serde("OptionalIdx");
                    format!(
                        "serializer.write_property_with_explicit_default({id}, {tag:?}, &{idx}({value}), &{idx}(None))?;"
                    )
                }
                Some(DefaultExpr::Expr(default)) => format!(
                    "serializer.write_property_with_explicit_default({id}, {tag:?}, &{value}, &{default})?;"
                ),
                None if has_default_by_default(&member.spec.cpp_type) => {
                    if member.required() {
                        format!("serializer.write_optional({id}, {tag:?}, false, &{value})?;")
                    } else {
                        format!("serializer.write_property_with_default({id}, {tag:?}, &{value})?;")
                    }
                }
                None if member.ty == CppType::OptionalIdx => {
                    let idx = self.serde("OptionalIdx");
                    format!("serializer.write_property({id}, {tag:?}, &{idx}({value}))?;")
                }
                None => format!("serializer.write_property({id}, {tag:?}, &{value})?;"),
            }
        };
        Ok(match (member.status, conditional) {
            (MemberStatus::Existing, false) => format!("        {stmt}\n"),
            (MemberStatus::Existing, true) => format!(
                "        if serializer.should_serialize({}) {{\n            {stmt}\n        }}\n",
                member.version
            ),
            _ => format!(
                "        if !serializer.should_serialize({}) {{\n            {stmt}\n        }}\n",
                member.version
            ),
        })
    }

    /// A member declared with a derived type but serialized as its hierarchy root
    /// (`"base"` in the spec): the root's discriminant precedes the derived members.
    fn base_parts(&mut self, member: &Member) -> Result<(&'m Class, Child)> {
        let base = member.spec.base.as_deref().ok_or("no base")?;
        let base_class = self
            .model
            .classes
            .get(base.trim_end_matches('*'))
            .ok_or_else(|| format!("unknown base {base}"))?;
        if base_class.shape != Shape::Enum {
            return Err(format!("base {base} must be a hierarchy with no shared members").into());
        }
        let CppType::Pointer(inner) = &member.ty else {
            return Err("base member must be a pointer".into());
        };
        let CppType::Named(derived) = inner.as_ref() else {
            return Err("base member must point to a class".into());
        };
        let child = base_class
            .children
            .iter()
            .find(|c| c.class == *derived)
            .cloned()
            .ok_or_else(|| format!("{derived} is not a subclass of {base}"))?;
        Ok((base_class, child))
    }

    fn write_base_member(&mut self, class: &Class, member: &Member) -> Result<String> {
        if !member.required() {
            return Err(format!(
                "{}.{}: base members must be required",
                class.spec.class, member.spec.name
            )
            .into());
        }
        let (base_class, child) = self.base_parts(member)?;
        let (_, index) = base_class.discriminant.clone().ok_or("no class type")?;
        let disc = &base_class.members[index];
        let value = self.discriminant_value(base_class, &child.enum_value)?;
        Ok(format!(
            "serializer.write_optional_with({}, {:?}, false, |serializer| {{\n\
             serializer.on_nullable_begin(true);\n\
             serializer.on_object_begin();\n\
             serializer.write_property({}, {:?}, &{value})?;\n\
             self.{}.serialize_fields(serializer)?;\n\
             serializer.on_object_end();\n\
             serializer.on_nullable_end();\n\
             Ok(())\n\
             }})?;",
            member.spec.id, member.spec.name, disc.spec.id, disc.spec.name, member.rust_name
        ))
    }

    /// A `let` statement reading one member into a local of the same name.
    fn read_member(&mut self, class: &Class, member: &Member, mutable: bool) -> Result<String> {
        let (id, tag) = (member.spec.id, &member.spec.name);
        if member.status != MemberStatus::Existing {
            if member.status == MemberStatus::ReadOnly {
                return Err(format!(
                    "{}.{}: read-only members need a custom class",
                    class.spec.class, member.spec.name
                )
                .into());
            }
            let ty = self.rust_type(&member.ty, true, false)?;
            return Ok(format!(
                "        deserializer.read_deleted_property::<{ty}>({id}, {tag:?})?;\n"
            ));
        }
        let ty = self.member_type(member)?;
        let binding = if mutable {
            format!("mut {}", member.rust_name)
        } else {
            member.rust_name.clone()
        };
        let expr = if member.spec.base.is_some() {
            self.read_base_member(class, member)?
        } else {
            match self.default_expr(member)? {
                Some(DefaultExpr::NullValue) => {
                    let value = self.named("Value")?;
                    format!(
                        "deserializer.read_property_with_explicit_default({id}, {tag:?}, {value}::default())?"
                    )
                }
                Some(DefaultExpr::InvalidIndex) => {
                    let idx = self.serde("OptionalIdx");
                    format!("deserializer.read_property_with_explicit_default({id}, {tag:?}, {idx}(None))?.0")
                }
                Some(DefaultExpr::Expr(default)) => {
                    format!("deserializer.read_property_with_explicit_default({id}, {tag:?}, {default})?")
                }
                None if has_default_by_default(&member.spec.cpp_type) => {
                    if member.required() {
                        let required = self.serde("required");
                        format!(
                            "{required}(deserializer.read_property_with_default({id}, {tag:?})?, {:?}, {tag:?})?",
                            class.spec.class
                        )
                    } else {
                        format!("deserializer.read_property_with_default({id}, {tag:?})?")
                    }
                }
                None if member.ty == CppType::OptionalIdx => {
                    let idx = self.serde("OptionalIdx");
                    format!("deserializer.read_property::<{idx}>({id}, {tag:?})?.0")
                }
                None => format!("deserializer.read_property({id}, {tag:?})?"),
            }
        };
        Ok(format!("        let {binding}: {ty} = {expr};\n"))
    }

    fn read_base_member(&mut self, class: &Class, member: &Member) -> Result<String> {
        let (base_class, child) = self.base_parts(member)?;
        let base_ty = self.named(&base_class.spec.class)?;
        let required = self.serde("required");
        let error = self.serde("Error");
        let child_class = self.child_class(&child)?;
        let value = if self.is_boxed(child_class) {
            "*value"
        } else {
            "value"
        };
        Ok(format!(
            "match *{required}::<Box<{base_ty}>>(deserializer.read_property_with_default({}, {:?})?, {:?}, {:?})? {{\n\
             {base_ty}::{}(value) => {value},\n\
             _ => return Err({error}::serialization(\"Failed to deserialize: property \\\"{}\\\" of {} has the wrong subclass\")),\n\
             }}",
            member.spec.id,
            member.spec.name,
            class.spec.class,
            member.spec.name,
            child.variant,
            member.spec.name,
            class.spec.class
        ))
    }
}

/// The `mod.rs` of a target's `generated` directory.
pub fn emit_mod_file(modules: &[Module]) -> String {
    let mut out = String::from("//! Code generated by `tools/codegen` from DuckDB's specs; do not edit.\n\n");
    for module in modules {
        let _ = writeln!(out, "pub mod {};", module.name);
    }
    out
}
